"""Figure for the solo decode -> reports/figures/bl_sd_summary.png"""
import sys, os, warnings, json; sys.path.insert(0, '.'); warnings.filterwarnings('ignore')
import matplotlib; matplotlib.use('Agg'); import matplotlib.pyplot as plt
from bl_common import *
FIG = os.path.join(os.path.dirname(OUT), 'reports', 'figures'); D = pd.read_pickle(f'{OUT}/bl_sd_orders.pkl.gz'); F = pd.read_csv(f'{OUT}/bl_sd_reactlots.csv'); U = pd.read_csv(f'{OUT}/bl_sd_state_auc.csv'); C = pd.read_csv(f'{OUT}/bl_sd_classes.csv'); T = pd.read_csv(f'{OUT}/bl_sd_combined.csv')
fig, ax = plt.subplots(2, 2, figsize=(14, 9.5))
a = ax[0, 0]; S = D[(D.typ == 'solo') & ~D.deep].sort_values(['cid', 'cp', 'te']); g = S.groupby(['cid', 'cp']).te.diff().dropna(); a.hist(g[g < 120], bins=np.arange(0, 121, 2), color='#1f77b4'); a.set_xlabel('seconds since the previous solo sale on the same side'); a.set_ylabel('solo sales'); a.set_title(f'A. Solo decisions come as bursts of 1-lot orders ({(g <= 3).mean():.0%} within 3 s)')
a = ax[0, 1]; F['bin'] = pd.cut(F.depth, [-10, 0, 0.1, 0.2, 0.4, 0.7, 1, 10]); t = F.groupby('bin', observed=True).agg(pairs=('pairs', 'mean'), extra=('extra_fav', 'mean'), n=('pairs', 'size')); x = np.arange(len(t)); a.bar(x - .2, t.pairs, .4, label='pairs per entry', color='#7f7f7f'); a.bar(x + .2, t.extra, .4, label='extra lots on the favourable side', color='#d62728'); a.set_xticks(x); a.set_xticklabels([str(i).replace('(-10.0', '(≤').replace(', 10.0]', ', >') for i in t.index], fontsize=7, rotation=20); a.set_xlabel('break beyond the two-candle channel (strike steps)'); a.legend(fontsize=8); a.set_title('B. Reactive entry size grows with the depth of the break')
for k, n in enumerate(t.n): a.text(k, max(t.pairs.iloc[k], t.extra.iloc[k]) + .05, f'n={n}', ha='center', fontsize=7)
a = ax[1, 0]; nm = {'last_ratio_ext': 'last-sold premium dips (minute low / sale price)', 'own_book': 'own side book ratio (profit < 1)', 'other_book': 'other side book ratio (loss > 1)', 'min_since_last': 'minutes since last sale on the side', 'spot_move_since_last': 'favourable spot move since last sale', 'imbalance': 'own lots − other lots', 'delta_toward': 'book delta toward the side', 'last_ratio_prev': 'last-sold premium, previous close', 'hour': 'time of day'}; u = U.copy(); u['label'] = u.variable.map(nm); u = u.iloc[(u.AUC - .5).abs().argsort()]; a.barh(u.label, u.AUC - .5, left=.5, color=['#d62728' if abs(v - .5) > .2 else '#7f7f7f' for v in u.AUC]); a.axvline(.5, color='k', lw=.8); a.set_xlim(.2, .8); a.set_xlabel('AUC, solo decision vs control minute (0.5 = no signal)'); a.set_title('C. State at a solo decision'); a.tick_params(axis='y', labelsize=8)
a = ax[1, 1]; c = C.set_index('solo_class'); x = np.arange(3); a.bar(x, c.share, color='#bbbbbb', label='share of regular solo lots'); a.bar(x, c.share * c.F1, color='#2ca02c', label='… reproduced (share × F1)'); a.set_xticks(x); a.set_xticklabels(['attached to\nreactive entries', 'intraday\nstand-alone', 'after 15:00'])
for k, (s_, f_) in enumerate(zip(c.share, c.F1)): a.text(k, s_ + .01, f'F1 {f_:.2f}', ha='center', fontsize=8)
tt = T[T.stream == 'all'].set_index('model'); a.set_title(f"D. Solo classes; all D-1 sells together: F1 {tt.F1.max():.2f}"); a.legend(fontsize=8)
plt.tight_layout(); plt.savefig(f'{FIG}/bl_sd_summary.png', dpi=130); print('ok')
